p=Path('frontend/src/routes/design-system/+page.svelte');s=p.read_text().replace('    ContentChange,','    ContentChange, Select, ViewButtons, ViewButton,');i=s.index('      <CategoryWheel');s=s[:i]+'''      <ViewButtons label="Example category buttons">
        <ViewButton selected={exampleUpdateCategory === "members"} onclick={() => exampleUpdateCategory = "members"}>MPs</ViewButton>
        <ViewButton selected={exampleUpdateCategory === "companies"} onclick={() => exampleUpdateCategory = "companies"}>Companies</ViewButton>
      </ViewButtons>
